INSERT INTO repo_cf_knowledge (cf_knowledge_id, education_level, sub_heading, text, status) VALUES ('CFK_SDG01_SEC_001', 'Secondary education', 'Understanding poverty', 'Poverty as a multidimensional issue, incorporating economic, social and political dimensions.', 'Active'), ('CFK_SDG01_SEC_002', 'Secondary education', 'Understanding poverty', 'Distinctions between: – absolute (extreme) poverty – for example, living on less than US$2.15/day. – relative poverty – disparities within and between societies. – monetary and multidimensional poverty, considering access to basic needs.', 'Active'), ('CFK_SDG01_SEC_003', 'Secondary education', 'Understanding poverty', 'Global poverty trends illustrated by comparative statistics and case studies.', 'Active'), ('CFK_SDG01_SEC_004', 'Secondary education', 'Understanding poverty', 'The relationship between scarcity of resources, economic development, inequality and livelihoods.', 'Active'), ('CFK_SDG01_SEC_005', 'Secondary education', 'Understanding poverty', 'Household poverty dynamics and the influence of national economic policies on family income and wellbeing.', 'Active'), ('CFK_SDG01_SEC_006', 'Secondary education', 'Causes and effects', 'Systemic causes of poverty, including: – lack of quality education and decent employment opportunities. – political instability and weak governance. – environmental degradation and climate change. – social exclusion and discrimination.', 'Active'), ('CFK_SDG01_SEC_007', 'Secondary education', 'Causes and effects', 'Effects of poverty, including:', 'Active'), ('CFK_SDG01_SEC_008', 'Secondary education', 'Causes and effects', 'limited access to nutrition, clean water, healthcare, education and safe housing.', 'Active'), ('CFK_SDG01_SEC_009', 'Secondary education', 'Causes and effects', 'child labour, exploitation and reliance on sweatshops.', 'Active'), ('CFK_SDG01_SEC_010', 'Secondary education', 'Causes and effects', 'intergenerational poverty and restricted upward mobility.', 'Active'), ('CFK_SDG01_SEC_011', 'Secondary education', 'Inequality and global context', 'The relationship between poverty, gender and resource distribution, including barriers to education and employment for women and girls, unequal wages, unpaid labour and limited access to finance.', 'Active'), ('CFK_SDG01_SEC_012', 'Secondary education', 'Inequality and global context', 'The role of inequality in perpetuating poverty, locally and globally.', 'Active'), ('CFK_SDG01_SEC_013', 'Secondary education', 'Inequality and global context', 'The influence of economic systems and global markets on poverty levels.', 'Active'), ('CFK_SDG01_SEC_014', 'Secondary education', 'Inequality and global context', 'The contribution of business practices, financial systems and consumer behaviour to poverty cycles and ethical dilemmas.', 'Active'), ('CFK_SDG01_SEC_015', 'Secondary education', 'Poverty reduction and solutions', 'Roles of governments, global organisations (such as the UN and World Bank) and non-governmental organisations (NGOs) in addressing poverty.', 'Active'), ('CFK_SDG01_SEC_016', 'Secondary education', 'Poverty reduction and solutions', 'Policy measures for poverty reduction, including social protection, taxation and provision of public services.', 'Active'), ('CFK_SDG01_SEC_017', 'Secondary education', 'Poverty reduction and solutions', 'Financial planning, inclusive economic models and fair trade as strategies for reducing poverty.', 'Active'), ('CFK_SDG01_SEC_018', 'Secondary education', 'Poverty reduction and solutions', 'Entrepreneurship, including youth-and women-led initiatives, and income-generating models such as co-operatives and social enterprises.', 'Active'), ('CFK_SDG01_TVET_001', 'TVET', 'Poverty', 'Poverty as a multidimensional challenge requiring economic, social, environmental and policy responses.', 'Active'), ('CFK_SDG01_TVET_002', 'TVET', 'Poverty', 'Absolute and relative poverty in relation to labour markets and livelihoods.', 'Active'), ('CFK_SDG01_TVET_003', 'TVET', 'Poverty', 'Links between poverty, employment, education and social services.', 'Active'), ('CFK_SDG01_TVET_004', 'TVET', 'Poverty', 'Effects of poverty on diverse groups (for example, youth, women, informal workers, and persons with disabilities) and its impact on access to decent work and fair wages.', 'Active'), ('CFK_SDG01_TVET_005', 'TVET', 'Poverty', 'Intersections between poverty, skills gaps, inequality and lack of opportunities in rural and urban economies.', 'Active'), ('CFK_SDG01_TVET_006', 'TVET', 'Causes and effects', 'Structural causes of poverty in vocational contexts, including: – unemployment, underemployment and low wages. – reliance on informal labour with limited rights and protections. – restricted access to training, finance, markets and infrastructure. – gender-based discrimination and inadequate childcare or support systems.', 'Active'), ('CFK_SDG01_TVET_007', 'TVET', 'Causes and effects', 'Consequences of poverty, including: – low productivity, poor health outcomes and reduced resilience. – intergenerational poverty driven by lack of skills and limited education.', 'Active'), ('CFK_SDG01_TVET_008', 'TVET', 'Causes and effects', 'Economic shocks, environmental changes and social exclusion as disruptions to vocational pathways and livelihoods.', 'Active'), ('CFK_SDG01_TVET_009', 'TVET', 'Inequality and global context', 'Inequality as a barrier to vocational training, job opportunities, technology and capital.', 'Active'), ('CFK_SDG01_TVET_010', 'TVET', 'Inequality and global context', 'Globalisation, technological change and urbanisation as drivers of income disparities.', 'Active'), ('CFK_SDG01_TVET_011', 'TVET', 'Inequality and global context', 'Employment trends and poverty levels across sectors, including formal, informal and gig economies.', 'Active'), ('CFK_SDG01_TVET_012', 'TVET', 'Inequality and global context', 'The role of gender, geography and migration in shaping poverty and livelihoods.', 'Active'), ('CFK_SDG01_TVET_013', 'TVET', 'Inequality and global context', 'Inclusive economic models, including fair trade, co-operatives, social enterprises, green industries and circular economies.', 'Active'), ('CFK_SDG01_TVET_014', 'TVET', 'Inequality and global context', 'Labour market needs and vocational pathways linked to entrepreneurship and self-employment.', 'Active'), ('CFK_SDG01_TVET_015', 'TVET', 'Poverty reduction and solutions', 'The role of TVET in poverty reduction through skills development, employability, entrepreneurship and self-employment.', 'Active'), ('CFK_SDG01_TVET_016', 'TVET', 'Poverty reduction and solutions', 'Support systems for youth, women and vulnerable groups in achieving decent work.', 'Active'), ('CFK_SDG01_TVET_017', 'TVET', 'Poverty reduction and solutions', 'Economically and environmentally sustainable enterprises within local and global markets.', 'Active'), ('CFK_SDG01_TVET_018', 'TVET', 'Poverty reduction and solutions', 'Policy, institutional frameworks and partnerships as enablers of decent work, fair wages and inclusive labour markets.', 'Active'), ('CFK_SDG01_TVET_019', 'TVET', 'Poverty reduction and solutions', 'TVET as a contributor to resilience in the context of technological change, climate impacts and global economic shifts.', 'Active'), ('CFK_SDG01_TER_001', 'Tertiary education', 'Understanding poverty', 'Poverty as a complex, multidimensional phenomenon shaped by economics, power, conflict, inequality, and environmental, social and political systems.', 'Active'), ('CFK_SDG01_TER_002', 'Tertiary education', 'Understanding poverty', 'Distinctions between absolute and relative poverty, and between monetary and multidimensional deprivation, with reference to indicators such as the MPI and SDG metrics.', 'Active'), ('CFK_SDG01_TER_003', 'Tertiary education', 'Understanding poverty', 'Poverty dynamics among diverse groups, including women, migrants, indigenous peoples, youth and persons with disabilities.', 'Active'), ('CFK_SDG01_TER_004', 'Tertiary education', 'Understanding poverty', 'Links between poverty, climate change, environmental degradation and disasters, and their role in vulnerability and exclusion.', 'Active'), ('CFK_SDG01_TER_005', 'Tertiary education', 'Causes and effects', 'Structural drivers such as colonial legacies, unequal trade, environmental stressors and labour market exclusion.', 'Active'), ('CFK_SDG01_TER_006', 'Tertiary education', 'Causes and effects', 'Contributing factors including unemployment, lack of education and healthcare, displacement and conflict.', 'Active'), ('CFK_SDG01_TER_007', 'Tertiary education', 'Causes and effects', 'Impacts on health, education, nutrition, housing, water, sanitation and human security.', 'Active'), ('CFK_SDG01_TER_008', 'Tertiary education', 'Causes and effects', 'Economic shocks—pandemics, crises and technological disruptions—as drivers of poverty and inequality.', 'Active'), ('CFK_SDG01_TER_009', 'Tertiary education', 'Causes and effects', 'The cyclical relationship between poverty and vulnerability, limiting resilience to crises and climate impacts.', 'Active'), ('CFK_SDG01_TER_010', 'Tertiary education', 'Inequality and global context', 'National and global inequality as a factor perpetuating poverty, especially for marginalised groups.', 'Active'), ('CFK_SDG01_TER_011', 'Tertiary education', 'Inequality and global context', 'Comparative poverty trends and inequality gaps across countries and regions, using global datasets and case studies.', 'Active'), ('CFK_SDG01_TER_012', 'Tertiary education', 'Inequality and global context', 'Intersectionality of gender, race, disability and geography in shaping experiences of poverty and exclusion.', 'Active'), ('CFK_SDG01_TER_013', 'Tertiary education', 'Inequality and global context', 'Wealth concentration and tax systems as determinants of mobility and public investment.', 'Active') ON CONFLICT DO NOTHING;